#!/usr/bin/env node
// Maintainer-side export of tools/selectors.json into a signed remote compat
// profile (schema dreamskin-compat-profile/1, see docs/compat-profile-design.md).
//
// The profile is signed with an ed25519 private key generated by
// tools/generate-compat-keypair.mjs. Signature canonicalization:
//   * take every top-level profile field EXCEPT "signature",
//   * serialize deterministically: object keys sorted lexicographically at
//     every depth (Array#sort default UTF-16 code-unit order, the client
//     replicates this exactly), no indentation, no extra whitespace,
//   * sign the UTF-8 bytes of that string with ed25519 (64-byte signature).
//
// selectors.json stays the single editable source: its selectors[] entries are
// copied verbatim (all fields, including notes); client-side projection is the
// client's job.

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const PROFILE_SCHEMA = "dreamskin-compat-profile/1";
const SELECTORS_SCHEMA = "codex-dream-skin-selectors/1";
const SIGNATURE_PREFIX = "ed25519:";
const DEFAULT_MIN_CLIENT = "1.7.2";
const DEFAULT_EXPIRES_DAYS = 180;
const DEFAULT_SELECTORS_PATH = path.join(REPO_ROOT, "tools", "selectors.json");
const DEFAULT_OUT_PATH = path.join(REPO_ROOT, "compat", "profile.json");
const DAY_MS = 24 * 60 * 60 * 1000;
const SEMVER_PATTERN = /^\d+\.\d+\.\d+(?:-[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$/;

// Deterministic JSON: recursive, key-sorted, whitespace-free. Non-finite
// numbers cannot be signed, so they fail closed instead of degrading to null.
export function canonicalJson(value) {
  if (value === null) return "null";
  switch (typeof value) {
    case "boolean":
      return value ? "true" : "false";
    case "number":
      if (!Number.isFinite(value)) throw new TypeError("non-finite numbers are not canonicalizable");
      return JSON.stringify(value);
    case "string":
      return JSON.stringify(value);
    case "object": {
      if (Array.isArray(value)) {
        return `[${value.map((entry) => canonicalJson(entry)).join(",")}]`;
      }
      const keys = Object.keys(value)
        .filter((key) => value[key] !== undefined)
        .sort();
      return `{${keys
        .map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`)
        .join(",")}}`;
    }
    default:
      throw new TypeError(`values of type ${typeof value} are not canonicalizable`);
  }
}

// The exact string whose UTF-8 bytes get signed (or verified).
export function profileSignaturePayload(profile) {
  const { signature: _ignored, ...payload } = profile;
  return canonicalJson(payload);
}

function asPrivateKey(key) {
  return key instanceof crypto.KeyObject ? key : crypto.createPrivateKey(key);
}

export function asPublicKey(key) {
  if (key instanceof crypto.KeyObject) return key;
  return crypto.createPublicKey({
    key: Buffer.from(key, "base64"),
    format: "der",
    type: "spki",
  });
}

function decodeSignature(signature) {
  if (typeof signature !== "string" || !signature.startsWith(SIGNATURE_PREFIX)) return null;
  const bytes = Buffer.from(signature.slice(SIGNATURE_PREFIX.length), "base64");
  return bytes.length === 64 ? bytes : null;
}

// Never throws on malformed input: an unparseable signature is simply invalid,
// which is the fail-closed posture the client must have as well.
export function verifyProfileSignature(profile, publicKey) {
  const signature = decodeSignature(profile?.signature);
  if (!signature) return false;
  try {
    return crypto.verify(
      null,
      Buffer.from(profileSignaturePayload(profile), "utf8"),
      asPublicKey(publicKey),
      signature,
    );
  } catch {
    return false;
  }
}

// Validates the selectors.json source and returns a verbatim deep copy of its
// selectors[] array. Fail-closed on schema drift and duplicate keys.
export function selectProfileSelectors(source) {
  if (!source || typeof source !== "object") {
    throw new Error("selectors source must be a JSON object");
  }
  if (source.schema !== SELECTORS_SCHEMA) {
    throw new Error(`selectors source schema must be "${SELECTORS_SCHEMA}", got ${JSON.stringify(source.schema)}`);
  }
  if (!Array.isArray(source.selectors) || source.selectors.length === 0) {
    throw new Error("selectors source must contain a non-empty selectors array");
  }
  const seen = new Set();
  for (const entry of source.selectors) {
    if (!entry || typeof entry !== "object") {
      throw new Error("every selectors entry must be an object");
    }
    if (typeof entry.key !== "string" || entry.key === "") {
      throw new Error("every selectors entry needs a non-empty string key");
    }
    if (typeof entry.selector !== "string" || entry.selector === "") {
      throw new Error(`selector entry "${entry.key}" needs a non-empty selector string`);
    }
    if (seen.has(entry.key)) {
      throw new Error(`duplicate selector key: ${entry.key}`);
    }
    seen.add(entry.key);
  }
  return structuredClone(source.selectors);
}

export function buildCompatProfile({
  selectorsSource,
  privateKey,
  revision,
  minClient = DEFAULT_MIN_CLIENT,
  issuedAt,
  expiresDays = DEFAULT_EXPIRES_DAYS,
}) {
  if (!Number.isInteger(revision) || revision <= 0) {
    throw new Error("revision must be a positive integer");
  }
  if (typeof minClient !== "string" || !SEMVER_PATTERN.test(minClient)) {
    throw new Error(`minClient must be a semver string (e.g. 1.7.2), got ${JSON.stringify(minClient)}`);
  }
  if (!Number.isInteger(expiresDays) || expiresDays <= 0) {
    throw new Error("expiresDays must be a positive integer");
  }
  const issuedMs = Date.parse(issuedAt);
  if (!Number.isFinite(issuedMs)) {
    throw new Error(`issuedAt must be an ISO 8601 timestamp, got ${JSON.stringify(issuedAt)}`);
  }
  const selectors = selectProfileSelectors(selectorsSource);
  const profile = {
    schema: PROFILE_SCHEMA,
    revision,
    issuedAt: new Date(issuedMs).toISOString(),
    expiresAt: new Date(issuedMs + expiresDays * DAY_MS).toISOString(),
    minClient,
    selectors,
  };
  const signature = crypto.sign(
    null,
    Buffer.from(profileSignaturePayload(profile), "utf8"),
    asPrivateKey(privateKey),
  );
  return {
    profile: { ...profile, signature: `${SIGNATURE_PREFIX}${signature.toString("base64")}` },
    payload: profileSignaturePayload(profile),
  };
}

function usage(out) {
  out.write(`usage: node tools/build-compat-profile.mjs --key <pem> --revision <n> [options]

Exports tools/selectors.json into a signed dreamskin-compat-profile/1 profile.

  --key <pem>          (required) ed25519 private key, PKCS8 PEM
  --revision <n>       (required) positive, monotonically increasing integer
  --min-client <ver>   minimum client semver (default: ${DEFAULT_MIN_CLIENT})
  --expires-days <n>   days until the profile expires (default: ${DEFAULT_EXPIRES_DAYS})
  --issued-at <ISO>    fixed issue timestamp for reproducible output (default: now)
  --selectors <path>   selectors source (default: tools/selectors.json)
  --out <path>         output file (default: compat/profile.json under the repo root)
`);
}

function parseArgs(argv) {
  const options = {
    key: null,
    revision: null,
    minClient: DEFAULT_MIN_CLIENT,
    expiresDays: DEFAULT_EXPIRES_DAYS,
    issuedAt: null,
    selectorsPath: DEFAULT_SELECTORS_PATH,
    out: DEFAULT_OUT_PATH,
  };
  const errors = [];
  const valueFlags = new Map([
    ["--key", "key"],
    ["--revision", "revision"],
    ["--min-client", "minClient"],
    ["--expires-days", "expiresDays"],
    ["--issued-at", "issuedAt"],
    ["--selectors", "selectorsPath"],
    ["--out", "out"],
  ]);
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === "--help" || arg === "-h") {
      options.help = true;
      return { options, errors };
    }
    let name = arg;
    let inline = null;
    const eq = arg.indexOf("=");
    if (arg.startsWith("--") && eq !== -1) {
      name = arg.slice(0, eq);
      inline = arg.slice(eq + 1);
    }
    const target = valueFlags.get(name);
    if (!target) {
      errors.push(`unknown argument: ${arg}`);
      continue;
    }
    const value = inline !== null ? inline : argv[(i += 1)];
    if (value === undefined) {
      errors.push(`${name} requires a value`);
      continue;
    }
    options[target] = value;
  }
  if (!options.key) errors.push("--key <pem> is required");
  if (options.revision === null) {
    errors.push("--revision <n> is required");
  } else if (!/^\d+$/.test(options.revision) || Number(options.revision) <= 0) {
    errors.push(`--revision must be a positive integer, got ${JSON.stringify(options.revision)}`);
  } else {
    options.revision = Number(options.revision);
  }
  if (!/^\d+$/.test(options.expiresDays) || Number(options.expiresDays) <= 0) {
    errors.push(`--expires-days must be a positive integer, got ${JSON.stringify(options.expiresDays)}`);
  } else {
    options.expiresDays = Number(options.expiresDays);
  }
  if (!SEMVER_PATTERN.test(options.minClient)) {
    errors.push(`--min-client must be a semver string, got ${JSON.stringify(options.minClient)}`);
  }
  if (options.issuedAt !== null && !Number.isFinite(Date.parse(options.issuedAt))) {
    errors.push(`--issued-at must be an ISO 8601 timestamp, got ${JSON.stringify(options.issuedAt)}`);
  }
  return { options, errors };
}

function readJsonFile(filePath, label) {
  let text;
  try {
    text = fs.readFileSync(filePath, "utf8");
  } catch (error) {
    throw new Error(`cannot read ${label} at ${filePath}: ${error.message}`);
  }
  try {
    return JSON.parse(text);
  } catch (error) {
    throw new Error(`${label} at ${filePath} is not valid JSON: ${error.message}`);
  }
}

function main(argv) {
  const { options, errors } = parseArgs(argv);
  if (options.help) {
    usage(process.stdout);
    return 0;
  }
  if (errors.length > 0) {
    for (const error of errors) console.error(`error: ${error}`);
    usage(process.stderr);
    return 1;
  }
  try {
    const privateKey = fs.readFileSync(options.key, "utf8");
    const selectorsSource = readJsonFile(options.selectorsPath, "selectors source");
    const issuedAt = options.issuedAt ?? new Date().toISOString();
    const { profile } = buildCompatProfile({
      selectorsSource,
      privateKey,
      revision: options.revision,
      minClient: options.minClient,
      issuedAt,
      expiresDays: options.expiresDays,
    });
    // Belt and braces: the written profile must verify against the public key
    // derived from the signing key before it is allowed to exist on disk.
    if (!verifyProfileSignature(profile, crypto.createPublicKey(asPrivateKey(privateKey)))) {
      throw new Error("internal error: self-verification of the fresh signature failed");
    }
    const outPath = path.resolve(options.out);
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, `${JSON.stringify(profile, null, 2)}\n`, "utf8");
    console.log(
      `signed compat profile rev ${profile.revision} -> ${outPath} ` +
        `(${profile.selectors.length} selectors, expires ${profile.expiresAt})`,
    );
    return 0;
  } catch (error) {
    console.error(`error: ${error.message}`);
    return 1;
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exit(main(process.argv.slice(2)));
}
